import{initializeApp}from'https://www.gstatic.com/firebasejs/12.18.0/firebase-app.js';
import{getAuth,onAuthStateChanged,signInWithEmailAndPassword,signOut,sendPasswordResetEmail,createUserWithEmailAndPassword,setPersistence,browserLocalPersistence}from'https://www.gstatic.com/firebasejs/12.18.0/firebase-auth.js';
import{getFirestore,doc,getDoc,collection,query,where,getDocs,orderBy,limit,writeBatch,setDoc,updateDoc,serverTimestamp,deleteDoc}from'https://www.gstatic.com/firebasejs/12.18.0/firebase-firestore.js';
const $=id=>document.getElementById(id),cfg=window.WILDENHORST_FIREBASE||{};let auth,db,user,profile,season;
const APP_VERSION='0.23';
let testPlayer=null,activating=false,substituteContext=null,lineupState=null,newSeasonWizard=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function waOpen(text){const dlg=$('waPreviewDialog'),ta=$('waPreviewText');if(!dlg||!ta)return;ta.value=String(text||'');dlg.showModal()}
function waSend(){const text=$('waPreviewText')?.value||'';const url='https://wa.me/?text='+encodeURIComponent(text);$('waPreviewDialog')?.close();const w=window.open(url,'_blank');if(!w)window.location.href=url}
function show(id){$(id)?.classList.remove('hidden')}function hide(id){$(id)?.classList.add('hidden')}
function admin(){return profile?.role==='admin'||profile?.role==='headAdmin'}function head(){return profile?.role==='headAdmin'}
function activeProfile(){return testPlayer||profile}
function testBanner(){return testPlayer?`<div class="test-banner">🧪 Testweergave: <b>${esc(testPlayer.name||testPlayer.displayName||testPlayer.id)}</b> <button id="stopTest" class="secondary">Stop testen</button></div>`:''}
function bindTestBanner(){const b=$('stopTest');if(b)b.onclick=()=>{testPlayer=null;home()}}
function keyDate(k){if(!k)return new Date(0);const[y,m,d]=k.split('-').map(Number);return new Date(y,m-1,d,12)}
function dateText(k,year=true){if(!k)return'';return new Intl.DateTimeFormat('nl-NL',{weekday:'long',day:'numeric',month:'long',...(year?{year:'numeric'}:{})}).format(keyDate(k))}
function toKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function timeText(v){return String(v||'18:00').slice(0,5)}
function closeOffset(day){return day==='wednesday'?3:day==='thursday'?2:day==='saturday'?0:1}
function closeAtWith(dateKey,day='friday',time='18:00'){const d=keyDate(dateKey);d.setDate(d.getDate()-closeOffset(day));const[h,m]=timeText(time).split(':').map(Number);d.setHours(h,m,0,0);return d}
function closeDayNl(day){return day==='wednesday'?'woensdag':day==='thursday'?'donderdag':day==='saturday'?'zaterdag':'vrijdag'}
function seasonId(){return season?.id||'2026-2027'}
function coupleNumber(id,data={}){const explicit=Number(data.number||data.coupleNumber);if(explicit)return explicit;const m=String(id||'').match(/(\d+)/);return m?Number(m[1]):''}
function coupleLabel(id,data={}){const n=coupleNumber(id,data),name=data.name||id||'Koppel';return `${n?`Koppel ${n} – `:''}${name}`}
function playerCoupleLabel(playerId,couples=[]){const c=couples.find(x=>(x.memberIds||[]).includes(playerId));return c?coupleLabel(c.id,c):''}

if(!cfg.configured){show('setup')}else{const app=initializeApp(cfg);auth=getAuth(app);db=getFirestore(app);setPersistence(auth,browserLocalPersistence);onAuthStateChanged(auth,authChanged)}
async function authChanged(u){if(activating)return;if(!u){user=profile=season=null;hide('main');hide('setup');show('login');return}user=u;const s=await getDoc(doc(db,'users',u.uid));if(!s.exists()){await signOut(auth);return}if(s.data().status!=='active'){const m=$('loginMessage');m.textContent='Je account is aangemaakt en wacht nog op goedkeuring door de beheerder.';m.className='message';show('loginMessage');await signOut(auth);return}profile={id:s.id,...s.data()};const qs=await getDocs(query(collection(db,'seasons'),where('active','==',true),limit(1)));season=qs.empty?null:{id:qs.docs[0].id,...qs.docs[0].data()};if(admin()&&season){try{await syncPublicRoster()}catch(e){console.warn('Publieke spelerslijst kon niet worden bijgewerkt',e)}}hide('login');show('main');go('home')}
$('loginForm')?.addEventListener('submit',async e=>{e.preventDefault();try{await signInWithEmailAndPassword(auth,$('email').value.trim(),$('password').value)}catch(_){const m=$('loginMessage');m.textContent='Inloggen is niet gelukt. Controleer e-mailadres en wachtwoord.';m.className='message error';show('loginMessage')}});
$('activateAccount')?.addEventListener('click',()=>{ $('activateEmail').value=$('email').value.trim(); $('activatePassword').value=''; $('activatePassword2').value=''; hide('activateMessage'); $('activateDialog').showModal()});
$('cancelActivate')?.addEventListener('click',()=>$('activateDialog').close());
$('activateForm')?.addEventListener('submit',async e=>{e.preventDefault();const email=$('activateEmail').value.trim().toLowerCase(),p1=$('activatePassword').value,p2=$('activatePassword2').value,m=$('activateMessage');if(p1!==p2){m.textContent='De twee wachtwoorden zijn niet hetzelfde.';m.className='message error';show('activateMessage');return}try{activating=true;const cred=await createUserWithEmailAndPassword(auth,email,p1);await setDoc(doc(db,'users',cred.user.uid),{email,role:'player',status:'pending',participantType:'pending',createdAt:serverTimestamp()});m.textContent='Gelukt! Je account is aangemaakt. De beheerder moet het nog één keer goedkeuren. Daarna kun je inloggen.';m.className='message';show('activateMessage');$('email').value=email;setTimeout(async()=>{try{await signOut(auth)}catch(_){}activating=false},300)}catch(err){activating=false;m.textContent=err?.code==='auth/email-already-in-use'?'Voor dit e-mailadres bestaat al een account. Probeer in te loggen of gebruik Wachtwoord vergeten.':'Account activeren is niet gelukt. Controleer het e-mailadres en wachtwoord.';m.className='message error';show('activateMessage')}});
$('forgotPassword')?.addEventListener('click',async()=>{const e=$('email').value.trim(),m=$('loginMessage');if(!e){m.textContent='Vul eerst je e-mailadres in.';m.className='message error';show('loginMessage');return}try{await sendPasswordResetEmail(auth,e);m.textContent='Er is een resetmail verstuurd.';m.className='message';show('loginMessage')}catch(_){m.textContent='De resetmail kon niet worden verstuurd.';m.className='message error';show('loginMessage')}});
$('forgotLogin')?.addEventListener('click',()=>$('forgotLoginDialog').showModal());$('waSend')?.addEventListener('click',waSend);$('waCancel')?.addEventListener('click',()=>$('waPreviewDialog').close());$('substituteSave')?.addEventListener('click',saveSubstituteProposal);$('substituteCancel')?.addEventListener('click',()=>{substituteContext=null;$('substituteDialog').close()});document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>go(b.dataset.route));
function nav(r){document.querySelectorAll('[data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===r))}function go(r){nav(r);if(r==='home')home();if(r==='couple')couple();if(r==='saturday')saturday();if(r==='standings')standings();if(r==='more')more()}
async function playDates(){if(!season)return[];const s=await getDocs(query(collection(db,'seasons',season.id,'playDates'),orderBy('dateKey')));return s.docs.map(d=>({id:d.id,...d.data()})).filter(d=>d.status!=='cancelled')}
function endMoment(d){const x=keyDate(d.dateKey);const[h,m]=(d.endTime||season?.endTime||'12:00').split(':').map(Number);x.setHours(h,m,0,0);return x}
function nextPlayDate(ds,now=new Date()){return ds.find(d=>endMoment(d)>=now)||null}
function previousPlayDate(ds,now=new Date()){return [...ds].reverse().find(d=>endMoment(d)<now)||null}
async function home(){
 const vp=activeProfile(),n=vp?.firstName||vp?.displayName||vp?.name||'';$('screen').innerHTML='<div class="card"><h2>Home</h2><p>Laden…</p></div>';
 const ds=await playDates(),now=new Date(),next=nextPlayDate(ds,now),prev=previousPlayDate(ds,now);let nextHtml='<div class="card"><b>Er is nog geen volgende speeldag ingesteld.</b></div>';
 if(next){
  const [plans,couplesSnap]=await Promise.all([getDocs(collection(db,'seasons',season.id,'playDates',next.id,'couplePlans')),getDocs(collection(db,'seasons',season.id,'couples'))]);
  const couples=couplesSnap.docs.map(x=>({id:x.id,...x.data()})).filter(x=>x.status!=='inactive').sort((a,b)=>coupleNumber(a.id,a)-coupleNumber(b.id,b));
  const total=couples.length,planMap=new Map(plans.docs.map(x=>[x.id,x.data()])),valid=couples.filter(c=>{const x=planMap.get(c.id);return x&&validPair(x.member1Status,x.member2Status)}),playing=[];
  valid.forEach(c=>{const x=planMap.get(c.id),parts=String(c.name||'').split(' – ');if(x.member1Status==='speelt')playing.push(parts[0]||x.member1Id);if(x.member2Status==='speelt')playing.push(parts[1]||x.member2Id);if(x.substituteName&&x.substituteApproval!=='pending'&&x.substituteApproval!=='rejected')playing.push(x.substituteName)});
  const missing=couples.filter(c=>!valid.includes(c)),need=valid.filter(c=>{const x=planMap.get(c.id);return x.member1Status==='afwezig'&&x.member2Status==='afwezig'&&(!x.substituteName||x.substituteApproval==='rejected')});const pendingSubs=valid.filter(c=>planMap.get(c.id)?.substituteName&&planMap.get(c.id)?.substituteApproval==='pending');
  const own=vp?.coupleId?planMap.get(vp.coupleId):null;let ownText='Nog niet ingevuld';if(own){const mineId=vp.playerId||vp.id;ownText=own.member1Id===mineId?statusLabel(own.member1Status):own.member2Id===mineId?statusLabel(own.member2Status):(own.member1Status==='speelt'||own.member2Status==='speelt'?'Koppel ingevuld':'Beide afwezig')}
  const close=next.closeAt?.toDate?next.closeAt.toDate():closeAtWith(next.dateKey,season?.defaultCloseDay,season?.defaultCloseTime);
  const filledLines=valid.map(c=>{const x=planMap.get(c.id),parts=String(c.name||'').split(' – '),who=x.member1Status==='speelt'?parts[0]:x.member2Status==='speelt'?parts[1]:x.substituteName||'Vervanger nodig',sub=x.substituteName?`<small class="${x.substituteApproval==='pending'||x.substituteApproval==='rejected'?'pending-text':''}">${x.substituteApproval==='pending'?'⏳ Wacht op goedkeuring beheerder':x.substituteApproval==='rejected'?'❌ Vervanger afgewezen – nieuwe vervanger nodig':'✅ Vervanger goedgekeurd'}</small>`:'';return `<div class="simple-row"><b>${esc(coupleLabel(c.id,c))}${sub}</b><span>${esc(who||'')}</span></div>`}).join('');
  const missingLines=missing.map(c=>`<div class="simple-row"><b>${esc(coupleLabel(c.id,c))}</b></div>`).join('');
  nextHtml=`<section class="hero next-hero"><div class="eyebrow">🎾 Volgende speeldag</div><h1>${esc(dateText(next.dateKey))}</h1><p><b>${esc(next.startTime||season?.startTime||'10:00')}–${esc(next.endTime||season?.endTime||'12:00')}</b> · ${Number(next.courtCount||season?.defaultCourts||2)} banen</p><div class="deadline"><b>Spelerskeuze wijzigen tot</b><br>⏰ ${esc(dateText(toKey(close),false))} ${esc(timeText(`${String(close.getHours()).padStart(2,'0')}:${String(close.getMinutes()).padStart(2,'0')}`))}</div><div class="home-stats"><button class="stat-btn" data-stat="playing"><b>${playing.length}</b><span>spelers die spelen</span></button><button class="stat-btn" data-stat="filled"><b>${valid.length}/${total}</b><span>koppels ingevuld</span></button><button class="stat-btn" data-stat="missing"><b>${missing.length}</b><span>nog invullen</span></button></div><div id="homeStatDetail"></div>${need.length?`<div class="message error">⚠️ ${need.length} ${need.length===1?'koppel heeft':'koppels hebben'} een vervanger nodig.</div>`:''}<div class="my-status"><b>Jouw spelerskeuze:</b> ${esc(ownText)}</div>${own?.substituteName?`<div class="home-sub ${own.substituteApproval==='pending'||own.substituteApproval==='rejected'?'pending-sub':''}"><b>👤 Vervanger: ${esc(own.substituteName)}</b><span>${own.substituteApproval==='pending'?'⏳ Wacht op goedkeuring beheerder':own.substituteApproval==='rejected'?'❌ Afgewezen – geef een nieuwe vervanger door':'✅ Goedgekeurd door beheerder'}</span></div>`:''}${pendingSubs.length&&(!own?.substituteName||own.substituteApproval!=='pending')?`<div class="message pending-sub">⏳ ${pendingSubs.length} ${pendingSubs.length===1?'vervanger wacht':'vervangers wachten'} op goedkeuring van de beheerder.</div>`:''}</section>`;
  const homeLineupSnap=await getDoc(doc(db,'seasons',season.id,'playDates',next.id,'public','lineup'));
  if(homeLineupSnap.exists()&&homeLineupSnap.data()?.published===true){const lc=homeLineupSnap.data().courts||[];nextHtml+=`<div class="card home-lineup"><h3>🎾 Baanindeling ${esc(dateText(next.dateKey,false))}</h3>${lc.map(c=>`<div class="home-court"><b>Baan ${esc(c.number)} · ${esc(c.mode||'Dubbel')}</b><div><span>${esc((c.teamA||[]).join(' & '))}</span><strong>tegen</strong><span>${esc((c.teamB||[]).join(' & '))}</span></div></div>`).join('')}<button class="link" data-go="saturday">Bekijk zaterdag →</button></div>`}
  setTimeout(()=>{const detail=$('homeStatDetail');document.querySelectorAll('[data-stat]').forEach(b=>b.onclick=()=>{const t=b.dataset.stat;detail.innerHTML=t==='playing'?`<div class="card stat-detail"><h3>Spelers die spelen</h3>${playing.length?playing.map(x=>`<div class="simple-row">${esc(x)}</div>`).join(''):'<p>Nog niemand gepland.</p>'}</div>`:t==='filled'?`<div class="card stat-detail"><h3>Koppels ingevuld</h3>${filledLines||'<p>Nog geen koppels ingevuld.</p>'}</div>`:`<div class="card stat-detail"><h3>Nog invullen</h3>${missingLines||'<p>Iedereen heeft ingevuld. ✓</p>'}</div>`})},0);
 }
 let lastHtml='<div class="card"><h3>🏆 Laatste uitslag</h3><p>Nog geen gespeelde zaterdag met uitslagen.</p></div>';
 if(prev){const rs=await getDocs(collection(db,'seasons',season.id,'playDates',prev.id,'results'));if(!rs.empty){lastHtml=`<div class="card"><h3>🏆 Laatste uitslag · ${esc(dateText(prev.dateKey,false))}</h3>${rs.docs.slice(0,4).map(x=>resultLine(x.data())).join('')}<button class="link" data-go="standings">Bekijk stand →</button></div>`}else{lastHtml=`<div class="card"><h3>🏆 Laatste speelzaterdag · ${esc(dateText(prev.dateKey,false))}</h3><p>Er zijn nog geen uitslagen ingevoerd.</p></div>`}}
 $('screen').innerHTML=`${testBanner()}<section class="welcome"><h2>Welkom${n?', '+esc(n):''}</h2><span>${esc(season?.name||'Actief seizoen')}</span></section>${nextHtml}${lastHtml}${admin()?'<div class="adminbar"><b>⚙️ Beheerder</b><button id="beheer">Open beheer</button></div>':''}<div class="tiles"><button class="tile" data-go="couple">👥<strong>Mijn koppel</strong><small>Wie speelt, reserve of afwezig is.</small></button><button class="tile" data-go="saturday">🎾<strong>Zaterdag</strong><small>Baanindeling en uitslagen.</small></button><button class="tile" data-go="standings">🏆<strong>Stand</strong><small>Punten per koppel.</small></button><button class="tile" data-go="more">ℹ️<strong>Uitleg & gegevens</strong><small>Spelregels en eigen gegevens.</small></button></div>`;
 $('screen').querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$('beheer')?.addEventListener('click',beheer);bindTestBanner()
}
function resultLine(r){const teamText=v=>Array.isArray(v)?v.join(' & '):v;const a=teamText(r.teamA)||r.teamAName||r.coupleAName||'Team A',b=teamText(r.teamB)||r.teamBName||r.coupleBName||'Team B',score=r.scoreText||r.score||'';return `<div class="result-line"><b>${esc(a)}</b><span>${esc(score||'–')}</span><b>${esc(b)}</b></div>`}
function statusLabel(s){return s==='speelt'?'Speelt':s==='reserve'?'Reserve':s==='afwezig'?'Afwezig':'Nog kiezen'}
function validPair(a,b){return (a==='speelt'&&(b==='reserve'||b==='afwezig'))||(b==='speelt'&&(a==='reserve'||a==='afwezig'))||(a==='afwezig'&&b==='afwezig')}
function planHint(a,b,n1,n2){if(a==='afwezig'&&b==='afwezig')return '⚠️ Beide afwezig — vervanger nodig.';if(a==='speelt')return `✓ ${esc(n1)} speelt${b==='afwezig'?'; '+esc(n2)+' is afwezig':'; '+esc(n2)+' is reserve'}.`;if(b==='speelt')return `✓ ${esc(n2)} speelt${a==='afwezig'?'; '+esc(n1)+' is afwezig':'; '+esc(n1)+' is reserve'}.`;return 'Kies wie speelt. De partner wordt automatisch Reserve.'}
async function couple(){
 const vp=activeProfile();$('screen').innerHTML=testBanner()+'<div class="card"><h2>Mijn koppel</h2><p>Laden…</p></div>';bindTestBanner();if(!vp?.coupleId){$('screen').innerHTML='<div class="card"><h2>Mijn koppel</h2><p>Nog geen koppel gekoppeld.</p></div>';return}
 const [c,dates]=await Promise.all([getDoc(doc(db,'seasons',season.id,'couples',vp.coupleId)),playDates()]);const cp=c.exists()?c.data():{},ids=Array.isArray(cp.memberIds)?cp.memberIds:[],nameParts=String(cp.name||'').split(' – '),names=[nameParts[0]||'Speler 1',nameParts[1]||'Speler 2'];const planSnaps=await Promise.all(dates.map(d=>getDoc(doc(db,'seasons',season.id,'playDates',d.id,'couplePlans',vp.coupleId))));
 const cpLabel=coupleLabel(vp.coupleId,cp);
 const todayKey=toKey(new Date()),pastDates=dates.filter(d=>d.dateKey<todayKey);
 const lineupSnaps=await Promise.all(pastDates.map(d=>getDoc(doc(db,'seasons',season.id,'playDates',d.id,'public','lineup'))));
 const subCounts=[0,0];
 lineupSnaps.forEach(snap=>{if(!snap.exists()||snap.data()?.published!==true)return;(snap.data().courts||[]).forEach(court=>{[['teamAIds','teamACoupleIds'],['teamBIds','teamBCoupleIds']].forEach(([idKey,coupleKey])=>{const pids=Array.isArray(court[idKey])?court[idKey]:[],cids=Array.isArray(court[coupleKey])?court[coupleKey]:[];ids.forEach((pid,idx)=>{if(pid&&pids.includes(pid)&&!cids.includes(vp.coupleId))subCounts[idx]++})})})});
 let html=`<div class="card"><h2>${esc(cpLabel)}</h2><p><b>Zo werkt het:</b> tik per zaterdag op <b>Speelt</b> bij degene die speelt. De partner wordt automatisch <b>Reserve</b>. Is iemand niet beschikbaar, kies <b>Afwezig</b>.</p><div id="coupleSummary"></div><div id="coupleStats" class="player-stats"></div><div class="message"><b>Invallen dit seizoen</b><br>${esc(names[0])}: <b>${subCounts[0]}×</b> ingevallen<br>${esc(names[1])}: <b>${subCounts[1]}×</b> ingevallen</div></div>`;
 dates.forEach((d,i)=>{const x=planSnaps[i].exists()?planSnaps[i].data():{},a=x.member1Status||'',b=x.member2Status||'',close=d.closeAt?.toDate?d.closeAt.toDate():closeAtWith(d.dateKey,season?.defaultCloseDay,season?.defaultCloseTime),pastClose=new Date()>=close,locked=!admin()&&pastClose,closeDay=new Intl.DateTimeFormat('nl-NL',{weekday:'long'}).format(close),closeTime=`${String(close.getHours()).padStart(2,'0')}:${String(close.getMinutes()).padStart(2,'0')}`;html+=`<div class="date-card plan-card" data-date="${esc(d.id)}" data-key="${esc(d.dateKey)}" data-id1="${esc(ids[0]||'')}" data-id2="${esc(ids[1]||'')}" data-s1="${esc(a)}" data-s2="${esc(b)}" data-saved1="${esc(a)}" data-saved2="${esc(b)}" data-subname="${esc(x.substituteName||'')}" data-subapproval="${esc(x.substituteApproval|| (x.substituteName?'approved':''))}"><div class="date-head"><b>${esc(dateText(d.dateKey))}</b><span class="status ${pastClose?'closed':''}">${pastClose?'🔒 Spelerskeuze gesloten':`🟢 Spelerskeuze open tot ${esc(closeDay)} ${esc(closeTime)}`}</span></div>${pastClose?'<div class="choice-deadline closed-note">De spelerskeuze is gesloten. Alleen een beheerder kan Speelt, Reserve of Afwezig nog wijzigen.</div>':''}<div class="planner-person"><strong>${esc(names[0])}</strong><div class="choice-row" data-who="1"><button type="button" data-status="speelt" ${locked?'disabled':''}>Speelt</button><button type="button" data-status="reserve" ${locked?'disabled':''}>Reserve</button><button type="button" data-status="afwezig" ${locked?'disabled':''}>Afwezig</button></div></div><div class="planner-person"><strong>${esc(names[1])}</strong><div class="choice-row" data-who="2"><button type="button" data-status="speelt" ${locked?'disabled':''}>Speelt</button><button type="button" data-status="reserve" ${locked?'disabled':''}>Reserve</button><button type="button" data-status="afwezig" ${locked?'disabled':''}>Afwezig</button></div></div><div class="plan-hint"></div><div class="substitute-info">${x.substituteName?`<div class="message ${x.substituteApproval==='pending'?'pending-sub':''}">👤 Vervanger: <b>${esc(x.substituteName)}</b>${x.substituteApproval==='pending'?'<br><span>⏳ Wacht op goedkeuring beheerder</span>':x.substituteApproval==='rejected'?'<br><span>❌ Afgewezen – geef een nieuwe vervanger door</span>':x.substituteApproval==='approved'?'<br><span>✅ Goedgekeurd</span>':''}</div>`:''}${x.substituteForCoupleLabel?`<div class="message">↪ ${esc(x.substitutePlayerName||'Een speler uit dit koppel')} valt in voor <b>${esc(x.substituteForCoupleLabel)}</b>.</div>`:''}</div><button type="button" class="wa-sub secondary ${a==='afwezig'&&b==='afwezig'?'':'hidden'}">💬 Vervanger gezocht via WhatsApp</button><button type="button" class="sub-propose ${a==='afwezig'&&b==='afwezig'&&x.member1Status==='afwezig'&&x.member2Status==='afwezig'?'':'hidden'}">👤 ${x.substituteName?'Vervanger wijzigen':'Vervanger doorgeven'}</button>${locked?'':`<button type="button" class="save-plan secondary" disabled>Keuze opgeslagen</button>`}<div class="plan-msg"></div></div>`});
 $('screen').innerHTML=html;document.querySelectorAll('.plan-card').forEach(card=>{paintPlan(card,names);card.querySelectorAll('.choice-row button').forEach(btn=>btn.onclick=()=>choosePlan(card,btn,names));card.querySelector('.save-plan')?.addEventListener('click',()=>savePlan(card,names));card.querySelector('.wa-sub')?.addEventListener('click',()=>waOpen(`🎾 Vervanger gezocht – Wildenhorst\n\n${cpLabel} zoekt voor ${dateText(card.dataset.key)} een vervanger.\n\nWie kan en wil invallen? Laat het even weten in de WhatsApp-groep.`));card.querySelector('.sub-propose')?.addEventListener('click',()=>openSubstituteProposal(card,cpLabel))});refreshCoupleSummary(names)
}
function refreshCoupleSummary(names){const cards=[...document.querySelectorAll('.plan-card')],now=new Date(),today=toKey(now);const filled=cards.filter(c=>validPair(c.dataset.saved1,c.dataset.saved2)).length;const count=(who,past)=>cards.filter(c=>{const s=who===1?c.dataset.saved1:c.dataset.saved2,isPast=c.dataset.key<today;return s==='speelt'&&(past?isPast:!isPast)}).length;$('coupleSummary').innerHTML=`<div class="message"><b>${filled} van ${cards.length}</b> speelzaterdagen ingevuld. Wijzigen kan tot ${esc(closeDayNl(season?.defaultCloseDay))} ${esc(timeText(season?.defaultCloseTime))}; daarna alleen de beheerder.</div>`;$('coupleStats').innerHTML=`<div><strong>${esc(names[0])}</strong><span>Gepland <b>${count(1,false)}</b></span><span>Gespeeld <b>${count(1,true)}</b></span></div><div><strong>${esc(names[1])}</strong><span>Gepland <b>${count(2,false)}</b></span><span>Gespeeld <b>${count(2,true)}</b></span></div>`}
function choosePlan(card,btn,names){const who=btn.closest('.choice-row').dataset.who,status=btn.dataset.status;let a=card.dataset.s1||'',b=card.dataset.s2||'';if(who==='1')a=status;else b=status;if(status==='speelt'){if(who==='1'&&b!=='afwezig')b='reserve';if(who==='2'&&a!=='afwezig')a='reserve'}if(status==='reserve'){if(who==='1')b='speelt';else a='speelt'}if(status==='afwezig'){if(who==='1'&&b==='reserve')b='speelt';if(who==='2'&&a==='reserve')a='speelt'}card.dataset.s1=a;card.dataset.s2=b;paintPlan(card,names)}
function paintPlan(card,names){const a=card.dataset.s1||'',b=card.dataset.s2||'';card.querySelectorAll('.choice-row').forEach(row=>{const s=row.dataset.who==='1'?a:b;row.querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x.dataset.status===s))});const h=card.querySelector('.plan-hint');if(h)h.innerHTML=planHint(a,b,names[0],names[1]);card.querySelector('.wa-sub')?.classList.toggle('hidden',!(a==='afwezig'&&b==='afwezig'));card.querySelector('.sub-propose')?.classList.toggle('hidden',!(card.dataset.saved1==='afwezig'&&card.dataset.saved2==='afwezig'));const save=card.querySelector('.save-plan');if(save){const changed=a!==(card.dataset.saved1||'')||b!==(card.dataset.saved2||'');save.disabled=!changed||!validPair(a,b);save.textContent=changed?'Wijziging opslaan':'Keuze opgeslagen'}}
async function savePlan(card,names){const vp=activeProfile(),a=card.dataset.s1||'',b=card.dataset.s2||'',btn=card.querySelector('.save-plan'),msg=card.querySelector('.plan-msg');if(!validPair(a,b)){msg.textContent='Kies een geldige combinatie.';msg.className='plan-msg error';return}btn.disabled=true;btn.textContent='Opslaan…';msg.textContent='';try{await setDoc(doc(db,'seasons',season.id,'playDates',card.dataset.date,'couplePlans',vp.coupleId),{coupleId:vp.coupleId,member1Id:card.dataset.id1,member1Status:a,member2Id:card.dataset.id2,member2Status:b,updatedBy:user.uid,updatedAt:serverTimestamp()},{merge:false});card.dataset.saved1=a;card.dataset.saved2=b;msg.textContent='✓ Opgeslagen';msg.className='plan-msg ok';refreshCoupleSummary(names);paintPlan(card,names);btn.textContent='Keuze opgeslagen';btn.disabled=true}catch(e){console.error(e);msg.textContent='Opslaan lukt niet. Controleer de Firestore-regels en de deadline.';msg.className='plan-msg error';btn.textContent='Wijziging opslaan';btn.disabled=false}}
async function openSubstituteProposal(card,cpLabel){
 if(card.dataset.saved1!=='afwezig'||card.dataset.saved2!=='afwezig'){const m=card.querySelector('.plan-msg');m.textContent='Sla eerst op dat jullie allebei afwezig zijn.';m.className='plan-msg error';return}
 substituteContext={card,cpLabel};const dlg=$('substituteDialog'),list=$('subReserveList'),name=$('subOtherName'),msg=$('substituteMessage');msg.textContent='';name.value='';list.innerHTML='<p>Laden…</p>';dlg.showModal();
 try{const snap=await getDoc(doc(db,'seasons',season.id,'public','roster')),res=snap.exists()&&Array.isArray(snap.data().reserves)?snap.data().reserves:[];list.innerHTML=res.length?res.map((r,i)=>{const id=typeof r==='string'?`legacy-${i}`:r.id,n=typeof r==='string'?r:r.name;return `<label class="sub-choice"><input type="radio" name="subReserve" value="${esc(id||'')}" data-name="${esc(n||'')}"> <span>${esc(n||'')}</span></label>`}).join(''):'<p>Er zijn geen reserves beschikbaar in de lijst.</p>'}catch(e){console.error(e);list.innerHTML='<p>De reservelijst kon niet worden geladen.</p>'}
}
