 const ctx=substituteContext;if(!ctx)return;const selected=document.querySelector('input[name="subReserve"]:checked'),other=$('subOtherName').value.trim(),msg=$('substituteMessage');let substituteId='',substituteName='',substituteType='';
 if(selected){substituteId=selected.value;substituteName=selected.dataset.name;substituteType='reserve'}else if(other){substituteId=`external-${user.uid}-${Date.now()}`;substituteName=other;substituteType='external'}else{msg.textContent='Kies een reserve of vul de naam van een andere vervanger in.';msg.className='message error';return}
