function more(){$('screen').innerHTML=`<div class="tiles"><button class="tile" id="data">👤<strong>Mijn gegevens</strong><small>Contactgegevens bekijken en wijzigen.</small></button><button class="tile" id="roster">👥<strong>Spelers & reserves</strong><small>Bekijk alle vaste koppels en reservespelers.</small></button><button class="tile" id="rules">📘<strong>Uitleg / spelregels</strong><small>Spelerskeuze, vervangers, punten en zoemer.</small></button>${admin()?'<button class="tile" id="admin">⚙️<strong>Beheer</strong><small>Seizoen, spelers, banen, uitslagen en betalingen.</small></button>':''}<button class="tile" id="logout">🚪<strong>Uitloggen</strong></button></div>`;$('rules').onclick=rules;$('roster').onclick=playersAndReserves;$('admin')?.addEventListener('click',beheer);$('logout').onclick=()=>signOut(auth);$('data').onclick=data}
async function syncPublicRoster(){if(!admin()||!season)return;const [cs,rs]=await Promise.all([getDocs(collection(db,'seasons',season.id,'couples')),getDocs(collection(db,'seasons',season.id,'reserves'))]);const couples=cs.docs.map(d=>({id:d.id,...d.data()})).filter(x=>x.status!=='inactive').sort((a,b)=>coupleNumber(a.id,a)-coupleNumber(b.id,b)).map(c=>({number:coupleNumber(c.id,c),names:String(c.name||'').split(' – ').filter(Boolean)}));const reserves=rs.docs.map(d=>({id:d.id,...d.data()})).filter(x=>x.status!=='inactive').map(r=>({id:r.id,name:String(r.name||'').trim()})).filter(r=>r.name).sort((a,b)=>a.name.localeCompare(b.name,'nl'));await setDoc(doc(db,'seasons',season.id,'public','roster'),{couples,reserves,updatedAt:serverTimestamp()},{merge:false})}
async function playersAndReserves(){$('screen').innerHTML='<div class="card"><h2>👥 Spelers & reserves</h2><p>Laden…</p></div>';if(admin()){try{await syncPublicRoster()}catch(e){console.warn(e)}}const snap=await getDoc(doc(db,'seasons',season.id,'public','roster'));if(!snap.exists()){$('screen').innerHTML='<div class="card"><h2>👥 Spelers & reserves</h2><p>De spelerslijst is nog niet beschikbaar. Vraag een beheerder de app één keer te openen.</p></div>';return}const d=snap.data(),couples=Array.isArray(d.couples)?d.couples:[],reserves=Array.isArray(d.reserves)?d.reserves:[];$('screen').innerHTML=`<div class="card roster-page"><h2>👥 Spelers & reserves</h2><h3>Vaste spelers</h3><div class="couple-grid">${couples.map(c=>`<div class="couple-card"><span>Koppel ${esc(c.number)}</span>${(c.names||[]).map(n=>`<b>${esc(n)}</b>`).join('')}</div>`).join('')}</div><h3>Reserves</h3><div class="reserve-list">${reserves.map(r=>`<div>${esc(typeof r==='string'?r:r.name)}</div>`).join('')||'<p>Geen reserves.</p>'}</div></div>`}
function rules(){$('screen').innerHTML=`<div class="card help"><h2>📘 Uitleg / spelregels</h2><h3>Koppels</h3><p>De vaste koppels hebben gedurende het seizoen een vast koppelnummer 1 t/m 8. Dit nummer blijft hetzelfde bij de spelerskeuze, stand, uitslagen en vervangers.</p><h3>Speeltijden</h3><p><b>Inspeeltijd:</b> 10.00 tot 10.15 uur.<br><b>Aanvang wedstrijd:</b> 10.15 uur.</p><h3>Spelerskeuze</h3><p>Per koppel speelt normaal één speler en staat de partner reserve. Beiden op <b>Speelt</b> kan niet. Zijn beiden afwezig, dan is een vervanger nodig.</p><h3>Vervanger gezocht</h3><p>Als beiden afwezig zijn, kan het koppel via WhatsApp een vervanger zoeken en daarna zelf een reserve of andere vervanger doorgeven. De beheerder moet die vervanger eerst goedkeuren. Pas na goedkeuring telt de vervanger mee voor de baanindeling. Een vaste speler uit een ander koppel kan alleen door een beheerder als vervanger worden toegewezen.</p><h3>Enkelspel</h3><p>Enkelspel is alleen een noodoplossing als de baanindeling daarom vraagt. Een speler kan aangeven hiervoor beschikbaar te zijn. <b>Enkelspel levert 0 competitiepunten op.</b></p><h3>Punten</h3><p>Een volledig gewonnen set levert 1 punt op. Een laatste set die door de zoemer niet wordt uitgespeeld levert ½ punt op voor het team dat leidt, mits minimaal 3 games zijn gespeeld door de leider. Bij gelijke games, bijvoorbeeld <b>3–3</b>, telt de puntenstand in de lopende game mee, bijvoorbeeld <b>30–15</b>.</p><h3>Zoemer</h3><p>Bij de zoemer stopt het spel direct. Alleen bij exact gelijke game- én puntenstand, bijvoorbeeld 5–5 en 30–30, wordt nog één beslissend punt gespeeld.</p></div>`}
function data(){const vp=activeProfile();$('screen').innerHTML=`${testBanner()}<div class="card"><h2>Mijn gegevens</h2><div class="formgrid"><div><label>Naam</label><div class="readonly">${esc(vp?.displayName||vp?.name||'')}</div></div><div><label>E-mailadres / inlognaam</label><div class="readonly">${esc(testPlayer?vp?.email||'':user?.email||'')}</div></div><div><label>Telefoonnummer</label><input id="myPhone" type="tel" value="${esc(vp?.phone||'')}" ${testPlayer?'disabled':''}></div><div><label>Enkelspel</label><select id="mySingles" ${testPlayer?'disabled':''}><option value="no" ${vp?.singlesAllowed!==true?'selected':''}>Nee</option><option value="yes" ${vp?.singlesAllowed===true?'selected':''}>Ja, alleen als het voor de baanindeling nodig is</option></select></div></div>${testPlayer?'<p>In testweergave kun je deze persoonsgegevens niet wijzigen.</p>':'<button id="saveMine">Wijzigingen opslaan</button><div id="myMsg"></div>'}</div>`;bindTestBanner();if(!testPlayer)$('saveMine').onclick=saveMyData}
