   box.querySelectorAll('[data-nsrole]').forEach(sel=>sel.onchange=()=>{const i=Number(sel.dataset.nsrole);w.people[i].newRole=sel.value;if(sel.value!=='fixed')w.people[i].coupleNo=''});
