   const missingText=missingCouples.map(c=>coupleLabel(c.id,c)).join('\n');
   host.innerHTML=`<div class="message">${playing.length} spelers die spelen · ${missingCouples.length} koppels nog niet ingevuld.</div>${approvalHtml}${missingCouples.length?`<div class="whatsapp-box"><h3>💬 Koppels herinneren</h3><p>${missingCouples.map(c=>`<b>${esc(coupleLabel(c.id,c))}</b>`).join('<br>')}</p><button id="missingWa">WhatsApp herinnering</button></div>`:''}${subHtml}<div class="compact-setting"><b>Banen: <span id="courtCountText">${lineupState.courtCount}</span></b> <button id="toggleCourts" class="link">Wijzigen</button><div id="courtChooser" class="hidden"><select id="dayCourts">${[0,1,2,3,4].map(n=>`<option value="${n}" ${n===lineupState.courtCount?'selected':''}>${n} ${n===1?'baan':'banen'}</option>`).join('')}</select> <button id="saveCourts" class="secondary">Opslaan</button></div></div><div class="admin-actions"><button id="autoLineup" ${playing.length<2?'disabled':''}>🎾 Automatische indeling maken</button><button id="redoLineup" class="secondary" ${playing.length<2?'disabled':''}>🔄 Opnieuw indelen</button></div><div class="whatsapp-box"><h3>💬 WhatsApp uitnodiging</h3><textarea id="inviteText" rows="9"></textarea><button id="inviteWa">WhatsApp openen</button></div><div id="courtDraft"></div><div class="admin-actions"><button id="publishLineup" ${playing.length<2?'disabled':''}>✓ Indeling zichtbaar maken voor iedereen</button></div><div id="lineupMsg">${pub.exists()&&pub.data().published?'Er staat al een gepubliceerde indeling. Opnieuw publiceren markeert de indeling als gewijzigd.':''}</div><div id="lineupShare"></div><details class="manual-pick"><summary>Spelers handmatig aanwijzen / testen</summary><p><small>Als beheerder kun je hier bijvoorbeeld 8 spelers aanvinken om de baanindeling te testen. Dit verandert hun eigen spelerskeuze niet.</small></p><div class="manual-grid">${all.map(p=>`<label><input type="checkbox" data-manual="${esc(p.id)}" ${playing.some(x=>x.id===p.id)?'checked':''}> ${esc(p.name||p.id)}</label>`).join('')}</div><button id="applyManual">Geselecteerde spelers gebruiken</button></details>`;
   const refreshInvite=()=>{$('inviteText').value=`Wildenhorst zaterdagcompetitie\n\nBeste tennissers,\n\n${dateText(d.dateKey)} spelen we weer!\n\nTijd: ${d.startTime||season?.startTime||'10:00'} tot ${d.endTime||season?.endTime||'12:00'} uur.\n\nLaat via de app weten wie van jullie koppel speelt.\n\nEr hebben zich al ${lineupState.players.length} spelers aangemeld.\n${missingCouples.length?`Nog ${missingCouples.length} koppels moeten hun keuze doorgeven.\n`:''}\nOpen de app:\nhttps://hogeterp.github.io/Wildenhorst/`};refreshInvite();
