function automaticLineup(){
 let p=[...lineupState.players].sort((a,b)=>Number(a.strength||5)-Number(b.strength||5));if(p.length===6){const eligible=p.filter(x=>x.singlesAllowed===true);if(eligible.length>=2){const s=[eligible[eligible.length-2],eligible[eligible.length-1]],ids=new Set(s.map(x=>x.id));p=[...p.filter(x=>!ids.has(x.id)),...s];lineupState.modes={1:'Dubbel',2:'Enkel'}}}
 const out=[];for(let i=0;i<p.length;i+=4){const g=p.slice(i,i+4);if(g.length===4)out.push(g[0],g[3],g[1],g[2]);else out.push(...g)}lineupState.players=out;paintCourts();$('lineupMsg').textContent='✓ Automatische indeling gemaakt op basis van speelsterkte. Controleer en wijzig desgewenst voordat je publiceert.';$('lineupMsg').className='message'
}

function courtModel(){
  const players=lineupState.players.slice(0,lineupState.courtCount*4);
  const courts=[];
  for(let i=0;i<players.length && courts.length<lineupState.courtCount;i+=4){
    const chunk=players.slice(i,i+4);
    const auto=chunk.length===2?(chunk.every(x=>x?.singlesAllowed===true)?'Enkel':'Nog in te delen'):chunk.length>=4?'Dubbel':'Nog in te delen';
    const number=courts.length+1;
    const mode=lineupState.modes[number]||auto;
    courts.push({number,mode,players:mode==='Enkel'?chunk.slice(0,2):chunk});
  }
  while(courts.length<lineupState.courtCount){
    const number=courts.length+1;
    courts.push({number,mode:lineupState.modes[number]||'Dubbel',players:[]});
  }
  return courts;
}

function paintCourts(){
 const host=$('courtDraft'),cs=courtModel();
 host.innerHTML=lineupState.courtCount===0?'<p><b>Deze zaterdag zijn geen banen beschikbaar.</b></p>':cs.map(c=>{
  const a=c.mode==='Dubbel'?c.players.slice(0,2):c.players.slice(0,1),b=c.mode==='Dubbel'?c.players.slice(2,4):c.players.slice(1,2);
  const team=x=>x.map(p=>`<button class="compact-player ${lineupState.selected===p.id?'picked':''}" data-pid="${esc(p.id)}"><span>${esc(p.name||p.displayName||p.id)}</span><small class="strength-badge" title="Speelsterkte">${Number(p.strength||5)}</small></button>`).join(' & ');
  return `<div class="court-card compact-court"><div class="court-title"><h3>Baan ${c.number} · ${esc(c.mode)}</h3><button class="link" data-modebtn="${c.number}">✏️ Baanindeling wijzigen</button></div><div class="court-edit hidden" id="mode${c.number}"><p><b>Wijzig hier de spelvorm of wissel spelers.</b><br><small>Spelvorm kies je hieronder. Spelers wisselen: tik eerst op een speler en daarna op de speler waarmee je hem wilt omwisselen, ook tussen twee banen.</small></p><label>Spelvorm</label><select data-mode="${c.number}"><option ${c.mode==='Dubbel'?'selected':''}>Dubbel</option><option ${c.mode==='Enkel'?'selected':''}>Enkel</option><option ${c.mode==='Niet gebruiken'?'selected':''}>Niet gebruiken</option></select></div>${c.mode==='Niet gebruiken'?'<p>Deze baan wordt niet gebruikt.</p>':`<div class="compact-match court-teams"><div><small class="team-label">Team A</small>${team(a)||'Nog in te delen'}</div><b>VS</b><div><small class="team-label">Team B</small>${team(b)||'Nog in te delen'}</div></div>`}</div>`
 }).join('');
 host.querySelectorAll('[data-pid]').forEach(b=>b.onclick=()=>swapPick(b.dataset.pid));
 host.querySelectorAll('[data-modebtn]').forEach(b=>b.onclick=()=>{$('mode'+b.dataset.modebtn).classList.toggle('hidden')});
 host.querySelectorAll('[data-mode]').forEach(sel=>sel.onchange=()=>{lineupState.modes[sel.dataset.mode]=sel.value;paintCourts()})
}
function swapPick(id){if(!lineupState.selected){lineupState.selected=id;paintCourts();return}if(lineupState.selected===id){lineupState.selected=null;paintCourts();return}const a=lineupState.players.findIndex(p=>p.id===lineupState.selected),b=lineupState.players.findIndex(p=>p.id===id);[lineupState.players[a],lineupState.players[b]]=[lineupState.players[b],lineupState.players[a]];lineupState.selected=null;paintCourts()}
